tests:
test({ sr: 'dopunjuje jednocifrene brojeve nulom', en: 'pads single-digit numbers with a zero' }, () => {
  expect(formatTime(5, 7)).toBe('05:07');
});
test({ sr: 'dvocifreni brojevi ostaju isti', en: 'two-digit numbers stay the same' }, () => {
  expect(formatTime(12, 30)).toBe('12:30');
});
test({ sr: 'nula je 00', en: 'zero is 00' }, () => {
  expect(formatTime(0, 0)).toBe('00:00');
});

hiddenTests:
test('only the seconds need padding', () => {
  expect(formatTime(12, 9)).toBe('12:09');
});
test('only the minutes need padding', () => {
  expect(formatTime(9, 59)).toBe('09:59');
});
test('minutes with more than two digits stay whole', () => {
  expect(formatTime(100, 5)).toBe('100:05');
});
test('the result is text', () => {
  expect(typeof formatTime(1, 1)).toBe('string');
});

solutions.code:
function formatTime(minutes, seconds) {
  const mm = minutes < 10 ? '0' + minutes : String(minutes);
  const ss = seconds < 10 ? '0' + seconds : String(seconds);
  return mm + ':' + ss;
}
